package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct {
	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string = "N"
var WsBigTotal decimal.Decimal = decimal.NewFromInt(0)
var WsWrapTotal decimal.Decimal = decimal.NewFromInt(0)
var WsSafeTotal decimal.Decimal = decimal.NewFromInt(0)
var WsOverflows int64 = 0
var WsCount int64 = 0
var WsHalf decimal.Decimal = decimal.NewFromInt(0)
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var amtFileLines []string
var amtFileIdx int
var currentRec AmtRec

func isOverflow(v decimal.Decimal, intDigits int) bool {
	// overflow if absolute integer part needs more than intDigits digits
	abs := v.Abs()
	intPart := abs.Truncate(0)
	// intPart == 0 => 1 digit (0) which always fits if intDigits>=1
	if intPart.Equal(decimal.Zero) {
		return false
	}
	s := intPart.String()
	// s may be like "12345"
	if strings.HasPrefix(s, "-") {
		s = s[1:]
	}
	// remove any sign already done by Abs
	// s may contain decimal point? Truncate(0) should not
	if len(s) > intDigits {
		return true
	}
	return false
}

func maxMod(intDigits int) decimal.Decimal {
	// 10^intDigits
	return decimal.NewFromInt(1).Shift(int32(intDigits))
}

func storeWrap(src decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	// truncate to target scale
	t := src.Truncate(int32(scale))
	if !isOverflow(t, intDigits) {
		return t
	}
	// drop high-order digits
	// keep low intDigits integer digits plus fractional
	intPart := t.Truncate(0)
	frac := t.Sub(intPart)
	mod := maxMod(intDigits)
	// for positive numbers, mod operation: intPart % mod
	// handle negative correctly as well (COBOL keeps sign? but values are positive)
	absMod := intPart.Abs().Mod(mod)
	// preserve sign of original integer part
	if intPart.Sign() < 0 {
		absMod = absMod.Neg()
	}
	return absMod.Add(frac)
}

func addNoSizeError(target *decimal.Decimal, intDigits int, scale int, delta decimal.Decimal) {
	sum := target.Add(delta)
	// For ADD without SIZE ERROR, store with wrap (drop high digits) truncated
	*target = storeWrap(sum, intDigits, scale)
}

func addWithSizeError(target *decimal.Decimal, intDigits int, scale int, delta decimal.Decimal) bool {
	sum := target.Add(delta)
	t := sum.Truncate(int32(scale))
	if isOverflow(t, intDigits) {
		return true // size error
	}
	*target = t
	return false
}

func formatEdited(v decimal.Decimal, pattern string) string {
	// pattern like "ZZ,ZZ9.99" or "ZZ,ZZ9.9"
	dotIdx := strings.Index(pattern, ".")
	var intPat, fracPat string
	if dotIdx >= 0 {
		intPat = pattern[:dotIdx]
		fracPat = pattern[dotIdx+1:]
	} else {
		intPat = pattern
		fracPat = ""
	}
	fracDigits := len(fracPat) // number of 9 after dot
	intDigits := 0
	for _, ch := range intPat {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	// handle overflow for display: drop high digits is done by store, but if still overflow, mimic
	// we also drop high digits here if needed
	// get integer and fractional parts truncated to fracDigits
	// v is already truncated to its pic scale, but fracDigits may be smaller (e.g., 1)
	// we need to truncate/format to fracDigits? For WS-HALF-ED scale 1 matches value scale 1.
	// For WS-AMT-ED etc scale 2 matches.
	// Use truncate to fracDigits for safety
	t := v.Truncate(int32(fracDigits))
	abs := t.Abs()
	intPart := abs.Truncate(0)
	fracPart := abs.Sub(intPart)

	// integer digits string padded
	intStr := intPart.String()
	// intPart.String() for 0 gives "0"
	if intStr == "0" {
		// keep as "0"
	} else {
		// remove possible minus already
	}
	// if intStr length > intDigits, drop high digits
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	// pad left with zeros to intDigits
	if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	}
	// prepare frac string with exactly fracDigits digits
	fracStr := ""
	if fracDigits > 0 {
		// get fractional value scaled
		// fracPart * 10^fracDigits truncated
		scaled := fracPart.Shift(int32(fracDigits)).Truncate(0)
		// scaled should be integer 0..10^fracDigits-1
		s := scaled.String()
		// pad
		if len(s) < fracDigits {
			s = strings.Repeat("0", fracDigits-len(s)) + s
		}
		// if negative? not needed
		fracStr = s
	}

	// Build integer formatted part
	// map digits to Z/9 positions
	digitIdx := 0
	// First pass to determine suppression: find first non-zero digit among integer digits
	firstNonZero := -1
	for i, ch := range intStr {
		if ch != '0' {
			firstNonZero = i
			break
		}
	}
	// suppression active until firstNonZero
	// if all zeros, suppression stays until before last digit? 9 forces display of zero
	// So suppression should be active for positions where digitIdx < firstNonZero
	// But need to map digitIdx to intStr index
	// Actually firstNonZero in terms of digit index
	// If all zeros, firstNonZero stays -1 => all Z positions suppressed
	var outInt strings.Builder
	for _, pc := range intPat {
		if pc == ',' {
			// comma is suppressed if still in leading zero zone
			// leading zone means digitIdx corresponds to position before firstNonZero
			// if firstNonZero==-1 => all suppressed => comma suppressed
			// if digitIdx < firstNonZero => suppressed
			// Actually comma sits between digits; its suppression depends on whether yet emitted non-zero
			if firstNonZero == -1 {
				outInt.WriteByte(' ')
			} else {
				if digitIdx <= firstNonZero {
					// if the next digit to come is still leading zero zone, comma suppressed?
					// For pattern ZZ,ZZ9: digits indices 0,1, comma, 2,3,4
					// If firstNonZero=1, digitIdx before comma is 2 (already beyond), so comma should show
					// So check if digitIdx < firstNonZero -> suppressed else not
					// digitIdx is count of digits already consumed before this comma
					// For comma, compare digitIdx < firstNonZero ?
					// Example value 1000 intStr "01000" firstNonZero=1 (digit '1' at index1)
					// At comma, digitIdx=2 (already consumed 2 digits) => 2 <1? false => show comma -> correct
					// For value 10 intStr "00010" firstNonZero=3, at comma digitIdx=2 => 2<3 true => suppress comma
					if digitIdx < firstNonZero || (firstNonZero == -1) {
						outInt.WriteByte(' ')
					} else {
						outInt.WriteByte(',')
					}
				} else {
					if digitIdx < firstNonZero {
						outInt.WriteByte(' ')
					} else {
						outInt.WriteByte(',')
					}
				}
			}
		} else if pc == 'Z' || pc == '9' {
			d := intStr[digitIdx]
			digitIdx++
			if pc == 'Z' {
				if firstNonZero == -1 {
					// all zeros
					outInt.WriteByte(' ')
				} else if digitIdx-1 < firstNonZero {
					outInt.WriteByte(' ')
				} else {
					outInt.WriteByte(d)
				}
			} else { // '9'
				outInt.WriteByte(d)
			}
		}
	}

	result := outInt.String()
	if dotIdx >= 0 {
		result += "." + fracStr
	}
	// result length should equal pattern length; pad if needed (should already)
	if len(result) < len(pattern) {
		result = strings.Repeat(" ", len(pattern)-len(result)) + result
	}
	// Handle sign: COBOL edited pics here are unsigned, ignore
	if t.Sign() < 0 {
		// For negative, would need to place minus? Not needed for this program
		// Prepend minus in leading space if exists
		// Simple: replace first space with '-'
		for i, c := range result {
			if c == ' ' {
				// replace
				rs := []byte(result)
				rs[i] = '-'
				result = string(rs)
				break
			} else if c == '0' {
				// should shift?
				break
			}
		}
	}
	return result
}

func mainPara() {
	// OPEN INPUT AMT-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty (COBOL would error)
		amtFileLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		for scanner.Scan() {
			line := scanner.Text()
			amtFileLines = append(amtFileLines, line)
		}
		f.Close()
	}
	amtFileIdx = 0
	performReadPara()
	for WsEofFlag != "Y" {
		performProcessPara()
	}
	// CLOSE handled
	performSummaryPara()
}

func performReadPara() { readPara() }
func readPara() {
	if amtFileIdx >= len(amtFileLines) {
		WsEofFlag = "Y"
		return
	}
	raw := amtFileLines[amtFileIdx]
	amtFileIdx++
	// pad with spaces to 11
	if len(raw) < 11 {
		raw = raw + strings.Repeat(" ", 11-len(raw))
	} else if len(raw) > 11 {
		raw = raw[:11]
	}
	arAcct := raw[0:4]
	arAmtRaw := raw[4:11] // 7 bytes
	// parse amount: treat spaces as '0' for digit positions
	var digitsBuilder strings.Builder
	for _, ch := range arAmtRaw {
		if ch >= '0' && ch <= '9' {
			digitsBuilder.WriteRune(ch)
		} else if ch == ' ' {
			digitsBuilder.WriteRune('0')
		} else {
			digitsBuilder.WriteRune(ch)
		}
	}
	digitsStr := digitsBuilder.String()
	if digitsStr == "" {
		digitsStr = "0"
	}
	// digitsStr should be 7 digits numeric
	n, _ := decimal.NewFromString(digitsStr)
	// actually NewFromString will parse as integer
	// Use shift -2
	// If digitsStr has 7 chars, integer value, need to divide by 100
	// decimal.New(n, -2) where n is integer value
	// Use decimal.NewFromString then Shift
	// simpler: parse int64
	var intVal int64
	fmt.Sscanf(digitsStr, "%d", &intVal)
	// Build decimal with scale 2
	amt := decimal.New(intVal, -2)
	currentRec = AmtRec{ArAcct: arAcct, ArAmt: amt}
}

func performProcessPara() { processPara() }
func processPara() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	addNoSizeError(&WsBigTotal, 7, 2, currentRec.ArAmt)
	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL
	WsWrapTotal = storeWrap(WsBigTotal, 5, 2)
	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA END-ADD
	isErr := addWithSizeError(&WsSafeTotal, 5, 2, currentRec.ArAmt)
	if isErr {
		performOverflowPara()
	}
	// ADD 1 TO WS-COUNT
	WsCount++
	if WsCount > 99 {
		WsCount = WsCount % 100 // drop high digits (low 2 digits)
	}
	// COMPUTE WS-HALF = AR-AMT / 2  (truncated)
	halfRaw := currentRec.ArAmt.Div(decimal.NewFromInt(2))
	// Truncate to 1 decimal (scale 1)
	halfTrunc := halfRaw.Truncate(1)
	WsHalf = storeWrap(halfTrunc, 5, 1)
	// MOVE to edited
	WsAmtEd = formatEdited(currentRec.ArAmt, "ZZ,ZZ9.99")
	WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
	WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
	WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")
	// DISPLAY
	fmt.Printf("%s %s %s %s %s\n", currentRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	performReadPara()
}

func performSummaryPara() { summaryPara() }
func summaryPara() {
	// DISPLAY "RECORDS: " WS-COUNT  (WS-COUNT is PIC 99, unedited numeric DISPLAY prints zero-padded to digit count? But spec says unedited numeric DISPLAY item such as PIC 9(5) prints zero-padded. For PIC 99, should print 2 digits zero padded)
	// However the DISPLAY statement is: DISPLAY "RECORDS: " WS-COUNT
	// Concatenated, so WS-COUNT printed as per its picture? Need to format as 2-digit zero padded
	// Similarly OVERFLOWS
	// Check: PIC 99 DISPLAY prints zero-padded to width 2? e.g., 3 -> "03"
	// We'll follow that
	countStr := fmt.Sprintf("%02d", WsCount)
	overStr := fmt.Sprintf("%02d", WsOverflows)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("OVERFLOWS: %s\n", overStr)
}

func performOverflowPara() { overflowPara() }
func overflowPara() {
	WsOverflows++
	if WsOverflows > 99 {
		WsOverflows = WsOverflows % 100
	}
}

func main() {
	mainPara()
}

