	}
	fracStr := ""
	if fracDigits > 0 {
		scaled := fracPart.Shift(int32(fracDigits)).Truncate(0)
		s := scaled.String()
		if len(s) < fracDigits {
			s = strings.Repeat("0", fracDigits-len(s)) + s
		}
		fracStr = s
	}

	firstNonZero := -1
	for i, ch := range intStr {
		if ch != '0' {
			firstNonZero = i
			break
		}
	}
	var outInt strings.Builder
	digitIdx := 0
	for _, pc := range intPat {
		if pc == ',' {
			if firstNonZero == -1 {
				outInt.WriteByte(' ')
			} else {
				if digitIdx <= firstNonZero {
					outInt.WriteByte(' ')
				} else {
					outInt.WriteByte(',')
				}
			}
		} else if pc == 'Z' || pc == '9' {
			d := intStr[digitIdx]
			digitIdx++
			if pc == 'Z' {
				if firstNonZero == -1 {
					outInt.WriteByte(' ')
				} else if digitIdx-1 < firstNonZero {
					outInt.WriteByte(' ')
				} else {
					outInt.WriteByte(d)
				}
			} else {
				outInt.WriteByte(d)
			}
		}
	}

	result := outInt.String()
	if dotIdx >= 0 {
		result += "." + fracStr
	}
	if len(result) < len(pattern) {
		result = strings.Repeat(" ", len(pattern)-len(result)) + result
	}
	if t.Sign() < 0 {
		for i, c := range result {
			if c == ' ' {
				rs := []byte(result)
				rs[i] = '-'
				result = string(rs)
				break
			} else if c == '0' {
				break
			}
		}
	}
	return result
}

func mainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		amtFileLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		for scanner.Scan() {
			line := scanner.Text()
			amtFileLines = append(amtFileLines, line)
		}
		f.Close()
	}
	amtFileIdx = 0
	performReadPara()
	for WsEofFlag != "Y" {
		performProcessPara()
	}
	performSummaryPara()
}

func performReadPara() { readPara() }
func readPara() {
	if amtFileIdx >= len(amtFileLines) {
		WsEofFlag = "Y"
		return
	}
	raw := amtFileLines[amtFileIdx]
	amtFileIdx++
	if len(raw) < 11 {
		raw = raw + strings.Repeat(" ", 11-len(raw))
	} else if len(raw) > 11 {
		raw = raw[:11]
	}
	arAcct := raw[0:4]
	arAmtRaw := raw[4:11]
	var digitsBuilder strings.Builder
	for _, ch := range arAmtRaw {
		if ch >= '0' && ch <= '9' {
			digitsBuilder.WriteRune(ch)
		} else if ch == ' ' {
			digitsBuilder.WriteRune('0')
		} else {
			digitsBuilder.WriteRune(ch)
		}
	}
	digitsStr := digitsBuilder.String()
	if digitsStr == "" {
		digitsStr = "0"
	}
	var intVal int64
	fmt.Sscanf(digitsStr, "%d", &intVal)
	amt := decimal.New(intVal, -2)
	currentRec = AmtRec{ArAcct: arAcct, ArAmt: amt}
}

func performProcessPara() { processPara() }
func processPara() {
	addNoSizeError(&WsBigTotal, 7, 2, currentRec.ArAmt)
	WsWrapTotal = storeWrap(WsBigTotal, 5, 2)
	isErr := addWithSizeError(&WsSafeTotal, 5, 2, currentRec.ArAmt)
	if isErr {
		performOverflowPara()
	}
	WsCount++
	if WsCount > 99 {
		WsCount = WsCount % 100
	}
	halfRaw := currentRec.ArAmt.Div(decimal.NewFromInt(2))
	halfTrunc := halfRaw.Truncate(1)
	WsHalf = storeWrap(halfTrunc, 5, 1)
	WsAmtEd = formatEdited(currentRec.ArAmt, "ZZ,ZZ9.99")
	WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
	WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
	WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")
	fmt.Printf("%s %s %s %s %s\n", currentRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	performReadPara()
}

func performSummaryPara() { summaryPara() }
func summaryPara() {
	countStr := fmt.Sprintf("%02d", WsCount)
	overStr := fmt.Sprintf("%02d", WsOverflows)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("OVERFLOWS: %s\n", overStr)
}

func performOverflowPara() { overflowPara() }
func overflowPara() {
	WsOverflows++
	if WsOverflows > 99 {
		WsOverflows = WsOverflows % 100
	}
}

func main() {
	mainPara()
}
